                const category = services[categoryId];
                let servicesHTML = Object.keys(category.items).map(name => `<div class="service-item" onclick="selectService(this, '${escapeHtml(name).replace(/'/g, `\\'`)}')"><div class="service-icon"><i class="fas ${category.icon}"></i></div><div class="service-info"><h4>${escapeHtml(name)}</h4></div></div>`).join('');
                const categoryDiv = document.createElement('div');
                categoryDiv.className = 'service-category';
                categoryDiv.innerHTML = `<div class="category-header" onclick="toggleCategory(this)"><div class="category-title"><span>${category.name}</span></div><i class="fas fa-chevron-down"></i></div><div class="category-services"><div>${servicesHTML}</div></div>`;
                sidebarContent.appendChild(categoryDiv);
            }
        }
        const toggleCategory = header => { const s = header.nextElementSibling; const c = header.querySelector('.fa-chevron-down'); s.classList.toggle('open'); c.style.transform = s.classList.contains('open') ? 'rotate(180deg)' : 'rotate(0deg)'; };
        function selectService(element, serviceName) { 
            document.querySelectorAll('.service-item.active').forEach(item => item.classList.remove('active'));
            element.classList.add('active');
            hideWelcome(); 
            mainHeaderTitle.textContent = serviceName; 
            showServiceInterface(serviceName); 
            closeSidebar(); 
        }
        async function sendMessage() { 
            const message = messageInput.value.trim(); 
            if (!message || AppState.isTyping) return; 
            hideWelcome(); 
            addUserMessage(message); 
            messageInput.value = ''; 
            sendBtn.disabled = true; 
            messageInput.style.height = 'auto'; 
            showTypingIndicator(); 
            try { 
                addAiMessage(`Jelenleg csak a szolgáltatásokat támogatom. Kérlek válassz egyet a menüből!`);
            } catch(e) { 
                addAiMessage(`**Hiba:** ${e.message}`); 
            } finally { 
                hideTypingIndicator(); 
            } 
        }
        const addUserMessage = content => { const div = document.createElement('div'); div.className = 'message user-message'; div.innerHTML = `<div class="user-bubble">${escapeHtml(content)}</div>`; messagesContainer.appendChild(div); scrollToBottom(); };
        function addAiMessage(content) { 
            const div = document.createElement('div'); 
            div.className = 'message ai-message'; 
            div.innerHTML = `<div class="ai-content">${marked.parse(content)}</div>`; 
            messagesContainer.appendChild(div); 
            if (typeof hljs !== 'undefined') hljs.highlightAll(); 
            scrollToBottom(); 
        }
        function showTypingIndicator() { 
            if(AppState.isTyping) return; 
            AppState.isTyping = true; 
            const i = document.createElement('div'); 
            i.id = 'typingIndicator'; 
            i.className = 'message ai-message'; 
            i.innerHTML = `<div style="background: var(--surface); padding: 10px 16px; border-radius: var(--radius-lg);"><div style="display:flex; gap:4px;"><div style="animation: typingPulse 1.4s infinite ease-in-out; background-color: var(--text-muted); width: 8px; height: 8px; border-radius: 50%;"></div><div style="animation: typingPulse 1.4s -0.16s infinite ease-in-out; background-color: var(--text-muted); width: 8px; height: 8px; border-radius: 50%;"></div><div style="animation: typingPulse 1.4s -0.32s infinite ease-in-out; background-color: var(--text-muted); width: 8px; height: 8px; border-radius: 50%;"></div></div></div><style>@keyframes typingPulse { 0%, 80%, 100% { transform: scale(0.8); opacity: 0.5; } 40% { transform: scale(1.2); opacity: 1; } }</style>`; 
            messagesContainer.appendChild(i); 
            scrollToBottom(); 
        }
        const hideTypingIndicator = () => { AppState.isTyping = false; const i = getEl('typingIndicator'); if (i) i.remove(); };
        const escapeHtml = text => { const d = document.createElement('div'); d.textContent = String(text); return d.innerHTML; };
        const scrollToBottom = () => messagesContainer.scrollTo({ top: messagesContainer.scrollHeight, behavior: 'smooth' });
        function setupEventListeners() {
            messageInput.addEventListener('input', () => { const hasText = messageInput.value.trim().length > 0; sendBtn.disabled = !hasText; messageInput.style.height = 'auto'; messageInput.style.height = `${Math.min(messageInput.scrollHeight, 200)}px`; });
            messageInput.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendMessage(); } });
            sidebarOverlay.addEventListener('click', closeSidebar);
        }
        function showServiceInterface(serviceName) {
            let interfaceHTML = '';
            switch (serviceName) {
                case 'AlphaFold 3++': interfaceHTML = getAlphaFoldInterface(); break;
                case 'Szekvencia Validálás': interfaceHTML = getSequenceValidationInterface(); break;
                case 'Szekvencia Elemzés': interfaceHTML = getSequenceAnalysisInterface(); break;
                case 'Backend Állapot': interfaceHTML = getHealthCheckInterface(); break;
                default: interfaceHTML = getGenericInterface(serviceName, 'Adja meg a bemeneti adatokat a számításhoz.'); break;
            }
            messagesContainer.innerHTML = interfaceHTML;
            if (serviceName === 'AlphaFold 3++') {
                const seqInput = getEl('proteinSequence');
                if (seqInput) seqInput.addEventListener('input', updateSequenceStats);
            }
        }
        const getAlphaFoldInterface = () => `<div class="service-interface"><header class="interface-header"><h2><i class="fas fa-dna accent"></i> AlphaFold 3++</h2><p>Fehérje struktúra előrejelzés AlphaFold3 modellel.</p></header><div class="interface-content"><section class="input-section"><h3>Protein Szekvencia</h3><textarea id="proteinSequence" placeholder="Írja be a protein szekvenciát (pl. MKTAYIAK...)..." rows="6"></textarea><div class="sequence-stats" style="margin-top: 8px; color: var(--text-muted); font-size: 0.85rem;"><span id="sequence-length">Hossz: 0</span></div></section><section class="input-section"><h3>Paraméterek</h3><div class="options-grid"><div class="option-group"><label>Recycle Iterations</label><input type="number" id="recycle-iterations" value="3" min="1" max="20"></div><div class="option-group"><label>Diffusion Samples</label><input type="number" id="diffusion-samples" value="1" min="1" max="10"></div></div></section><div class="action-buttons"><button class="primary-btn" onclick="runAlphaFoldPrediction()"><i class="fas fa-play"></i> Predikció Indítása</button></div><div id="service-results"></div></div></div>`;
        const getSequenceValidationInterface = () => `<div class="service-interface"><header class="interface-header"><h2><i class="fas fa-check-circle accent"></i> Szekvencia Validálás</h2><p>Ellenőrizze, hogy a szekvencia érvényes-e.</p></header><div class="interface-content"><section class="input-section"><h3>Protein Szekvencia</h3><textarea id="validateSequence" placeholder="Írja be a protein szekvenciát..." rows="6"></textarea></section><div class="action-buttons"><button class="primary-btn" onclick="runSequenceValidation()"><i class="fas fa-check"></i> Validálás</button></div><div id="service-results"></div></div></div>`;
        const getSequenceAnalysisInterface = () => `<div class="service-interface"><header class="interface-header"><h2><i class="fas fa-chart-line accent"></i> Szekvencia Elemzés</h2><p>Elemezze a protein szekvenciát.</p></header><div class="interface-content"><section class="input-section"><h3>Protein Szekvencia</h3><textarea id="analyzeSequence" placeholder="Írja be a protein szekvenciát..." rows="6"></textarea></section><div class="action-buttons"><button class="primary-btn" onclick="runSequenceAnalysis()"><i class="fas fa-search"></i> Elemzés</button></div><div id="service-results"></div></div></div>`;
        const getHealthCheckInterface = () => `<div class="service-interface"><header class="interface-header"><h2><i class="fas fa-heartbeat accent"></i> Backend Állapot</h2><p>Ellenőrizze a backend szolgáltatás állapotát.</p></header><div class="interface-content"><div class="action-buttons"><button class="primary-btn" onclick="runHealthCheck()"><i class="fas fa-sync"></i> Állapot Lekérdezése</button></div><div id="service-results"></div></div></div>`;
        const getGenericInterface = (name, desc) => `<div class="service-interface"><header class="interface-header"><h2>${name}</h2><p>${desc}</p></header><div class="interface-content"><section class="input-section"><textarea id="serviceInput" placeholder="Bemeneti adatok..." rows="8"></textarea></section><div class="action-buttons"><button class="primary-btn" onclick="alert('Ez a szolgáltatás még nem elérhető.')"><i class="fas fa-play"></i> Indítás</button></div><div id="service-results"></div></div></div>`;
        const switchTab = (btn, tabId) => { btn.parentElement.querySelector('.active').classList.remove('active'); btn.classList.add('active'); btn.closest('.interface-content').querySelector('.tab-content.active').classList.remove('active'); getEl(tabId).classList.add('active'); };
        const updateSequenceStats = () => { const seqInput = getEl('proteinSequence'); if (seqInput) getEl('sequence-length').textContent = `Hossz: ${seqInput.value.replace(/[^A-Za-z]/g, '').length}`; };
        async function runAlphaFoldPrediction() {
            const sequence = getEl('proteinSequence').value.trim();
            const numRecycles = parseInt(getEl('recycle-iterations').value) || 3;
            const numDiffusionSamples = parseInt(getEl('diffusion-samples').value) || 1;
            if (!sequence) {
                showError("Kérlek adj meg egy protein szekvenciát.");
                return;
            }
            const payload = {
                protein_sequence: sequence,
                num_recycles: numRecycles,
                num_diffusion_samples: numDiffusionSamples
            };
            await showProgressAndRun('AlphaFold 3++ Predikció', async () => {
                const response = await callBackendAPI('/api/predict', payload);
                AppState.currentJobId = response.job_id;
                let resultsHTML = `<h3><i class="fas fa-check-circle accent"></i> Predikció Elindítva</h3><div class="result-card">`;
                if (response.job_id) {
                    resultsHTML += `<div class="status-indicator status-running"><i class="fas fa-spinner fa-spin"></i> Job ID: ${response.job_id}</div>`;
                    resultsHTML += `<div class="action-buttons" style="margin-top: 20px;"><button class="secondary-btn" onclick="checkJobStatus('${response.job_id}')"><i class="fas fa-sync"></i> Állapot Ellenőrzése</button></div>`;
                }
                if (response.pdb_content) {
                    resultsHTML += `<div class="action-buttons" style="margin-top: 20px;"><button class="primary-btn" onclick="downloadPDB('${response.job_id}')"><i class="fas fa-download"></i> PDB Letöltése</button></div>`;
                }
                resultsHTML += `</div>`;
                getEl('service-results').innerHTML = resultsHTML;
            });
        }
        async function checkJobStatus(jobId) {
            try {
                const response = await callBackendAPI(`/api/predict/${jobId}`, null, 'GET');
                let statusHTML = `<h3><i class="fas fa-info-circle accent"></i> Job Állapot</h3><div class="result-card">`;
                if (response.status === 'completed' && response.results) {
                    statusHTML += `<div class="status-indicator status-success"><i class="fas fa-check"></i> Kész</div>`;
                    statusHTML += `<div class="stats-grid" style="margin-top: 20px;">`;
                    if (response.results.plddt !== undefined) {
                        statusHTML += `<div class="stat-item"><span class="stat-number">${response.results.plddt.toFixed(1)}</span><span class="stat-label">pLDDT</span></div>`;
                    }
                    if (response.results.ptm !== undefined) {
                        statusHTML += `<div class="stat-item"><span class="stat-number">${response.results.ptm.toFixed(3)}</span><span class="stat-label">pTM</span></div>`;
                    }
                    if (response.results.iptm !== undefined) {
                        statusHTML += `<div class="stat-item"><span class="stat-number">${response.results.iptm.toFixed(3)}</span><span class="stat-label">ipTM</span></div>`;
                    }
                    statusHTML += `</div>`;
                    statusHTML += `<div class="action-buttons" style="margin-top: 20px;"><button class="primary-btn" onclick="downloadPDB('${jobId}')"><i class="fas fa-download"></i> PDB Letöltése</button></div>`;
                } else if (response.status === 'running') {
                    statusHTML += `<div class="status-indicator status-running"><i class="fas fa-spinner fa-spin"></i> Futás közben...</div>`;
                    statusHTML += `<div class="action-buttons" style="margin-top: 20px;"><button class="secondary-btn" onclick="checkJobStatus('${jobId}')"><i class="fas fa-sync"></i> Újraellenőrzés</button></div>`;
                } else if (response.status === 'failed') {
                    statusHTML += `<div class="status-indicator status-error"><i class="fas fa-times"></i> Hiba: ${response.error || 'Ismeretlen hiba'}</div>`;
                } else {
                    statusHTML += `<div class="status-indicator status-running"><i class="fas fa-clock"></i> Állapot: ${response.status || 'ismeretlen'}</div>`;
                }
                statusHTML += `</div>`;
                getEl('service-results').innerHTML = statusHTML;
            } catch (error) {
                showError(`Hiba az állapot ellenőrzésekor: ${error.message}`);
            }
        }
        async function downloadPDB(jobId) {
            try {
                window.open(`/api/predict/${jobId}/pdb`, '_blank');
            } catch (error) {
                showError(`Hiba a PDB letöltésekor: ${error.message}`);
            }
        }
        async function runSequenceValidation() {
            const sequence = getEl('validateSequence').value.trim();
            if (!sequence) {
                showError("Kérlek adj meg egy protein szekvenciát.");
                return;
            }
            await showProgressAndRun('Szekvencia Validálás', async () => {
                const response = await callBackendAPI('/api/validate', { sequence: sequence });
                let resultsHTML = `<h3><i class="fas fa-check-circle accent"></i> Validálási Eredmények</h3><div class="result-card">`;
                if (response.valid) {
                    resultsHTML += `<div class="status-indicator status-success"><i class="fas fa-check"></i> A szekvencia érvényes</div>`;
                    resultsHTML += `<div class="stats-grid" style="margin-top: 20px;">`;
                    resultsHTML += `<div class="stat-item"><span class="stat-number">${response.length || 0}</span><span class="stat-label">Hossz</span></div>`;
                    resultsHTML += `<div class="stat-item"><span class="stat-number">${response.amino_acids || 0}</span><span class="stat-label">Aminosavak</span></div>`;
                    resultsHTML += `</div>`;
                } else {
                    resultsHTML += `<div class="status-indicator status-error"><i class="fas fa-times"></i> Érvénytelen szekvencia: ${response.error || 'Ismeretlen hiba'}</div>`;
                }
                resultsHTML += `</div>`;
                getEl('service-results').innerHTML = resultsHTML;
            });
        }
        async function runSequenceAnalysis() {
            const sequence = getEl('analyzeSequence').value.trim();
            if (!sequence) {
                showError("Kérlek adj meg egy protein szekvenciát.");
                return;
            }
            await showProgressAndRun('Szekvencia Elemzés', async () => {
                const response = await callBackendAPI('/api/analyze', { sequence: sequence });
                let resultsHTML = `<h3><i class="fas fa-chart-line accent"></i> Elemzési Eredmények</h3><div class="result-card">`;
                resultsHTML += `<div class="stats-grid" style="margin-top: 20px;">`;
                if (response.length !== undefined) {
                    resultsHTML += `<div class="stat-item"><span class="stat-number">${response.length}</span><span class="stat-label">Hossz</span></div>`;
                }
                if (response.molecular_weight !== undefined) {
                    resultsHTML += `<div class="stat-item"><span class="stat-number">${response.molecular_weight.toFixed(2)}</span><span class="stat-label">Molekulatömeg</span></div>`;
                }
                if (response.isoelectric_point !== undefined) {
                    resultsHTML += `<div class="stat-item"><span class="stat-number">${response.isoelectric_point.toFixed(2)}</span><span class="stat-label">Izoelektromos pont</span></div>`;
                }
                if (response.hydrophobicity !== undefined) {
                    resultsHTML += `<div class="stat-item"><span class="stat-number">${response.hydrophobicity.toFixed(2)}</span><span class="stat-label">Hidrofobicitás</span></div>`;
                }
                resultsHTML += `</div></div>`;
                getEl('service-results').innerHTML = resultsHTML;
            });
        }
        async function runHealthCheck() {
            await showProgressAndRun('Backend Állapot', async () => {
                const response = await callBackendAPI('/api/health', null, 'GET');
                let resultsHTML = `<h3><i class="fas fa-heartbeat accent"></i> Rendszer Állapot</h3><div class="result-card">`;
                if (response.status === 'healthy' || response.status === 'ok') {
                    resultsHTML += `<div class="status-indicator status-success"><i class="fas fa-check"></i> A backend szolgáltatás működik</div>`;
                    resultsHTML += `<div class="stats-grid" style="margin-top: 20px;">`;
                    if (response.version) {
                        resultsHTML += `<div class="stat-item"><span class="stat-number">${response.version}</span><span class="stat-label">Verzió</span></div>`;
                    }
                    if (response.uptime) {
                        resultsHTML += `<div class="stat-item"><span class="stat-number">${response.uptime}</span><span class="stat-label">Uptime</span></div>`;
                    }
                    if (response.requests) {
                        resultsHTML += `<div class="stat-item"><span class="stat-number">${response.requests}</span><span class="stat-label">Kérések</span></div>`;
                    }
                    resultsHTML += `</div>`;
                } else {
                    resultsHTML += `<div class="status-indicator status-error"><i class="fas fa-times"></i> A backend nem elérhető</div>`;
                }
                resultsHTML += `</div>`;
                getEl('service-results').innerHTML = resultsHTML;
            });
        }
        function showError(message) {
            const resultsDiv = getEl('service-results');
            if (resultsDiv) {
                resultsDiv.innerHTML = `<div class="result-card"><div class="status-indicator status-error"><i class="fas fa-exclamation-triangle"></i> ${escapeHtml(message)}</div></div>`;
            }
        }
        async function showProgressAndRun(taskName, taskFunction) {
            const resultsDiv = getEl('service-results');
            if (resultsDiv) {
                resultsDiv.innerHTML = `<div class="result-card"><div class="status-indicator status-running"><i class="fas fa-spinner fa-spin"></i> ${escapeHtml(taskName)} folyamatban...</div></div>`;
            }
            try {
                await taskFunction();
            } catch (error) {
                showError(`Hiba történt: ${error.message}`);
            }
        }
        function init() {
            createSVGLogo();
            loadServices();
            setupEventListeners();
            new DynamicThemeManager();
        }
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init);
        } else {
            init();
        }
    </script>
</body>
</html>
